use super::*;
fn w16(b:&mut[u8],at:usize,n:u16){b[at..at+2].copy_from_slice(&n.to_le_bytes());}
fn w32(b:&mut[u8],at:usize,n:u32){b[at..at+4].copy_from_slice(&n.to_le_bytes());}
fn stored(name:&str,bytes:&[u8])->Vec<u8>{
    let mut b=vec![0;30];b[..4].copy_from_slice(b"PK\x03\x04");w16(&mut b,4,20);w32(&mut b,14,crc32(bytes));w32(&mut b,18,bytes.len()as u32);w32(&mut b,22,bytes.len()as u32);w16(&mut b,26,name.len()as u16);b.extend(name.as_bytes());b.extend(bytes);
    let start=b.len();let mut c=vec![0;46];c[..4].copy_from_slice(b"PK\x01\x02");w16(&mut c,4,20);w16(&mut c,6,20);w32(&mut c,16,crc32(bytes));w32(&mut c,20,bytes.len()as u32);w32(&mut c,24,bytes.len()as u32);w16(&mut c,28,name.len()as u16);c.extend(name.as_bytes());b.extend(&c);
    let mut e=vec![0;22];e[..4].copy_from_slice(b"PK\x05\x06");w16(&mut e,8,1);w16(&mut e,10,1);w32(&mut e,12,c.len()as u32);w32(&mut e,16,start as u32);b.extend(e);b
}
fn dirent(name:&[u8;11],attrs:u8,cluster:u16,size:usize)->[u8;32]{let mut e=[0;32];e[..11].copy_from_slice(name);e[11]=attrs;w16(&mut e,26,cluster);w32(&mut e,28,size as u32);e}
fn image(partitioned:bool)->Vec<u8>{
    let base=if partitioned{63*512}else{0};let sectors=4133;let mut b=vec![0;base+sectors*512];
    if partitioned{b[446+4]=4;w32(&mut b,446+8,63);w32(&mut b,446+12,sectors as u32);b[510..512].copy_from_slice(&[0x55,0xaa]);}
    let boot=&mut b[base..base+512];boot[..3].copy_from_slice(&[0xeb,0x3c,0x90]);w16(boot,11,512);boot[13]=1;w16(boot,14,1);boot[16]=2;w16(boot,17,32);w16(boot,19,sectors as u16);boot[21]=0xf8;w16(boot,22,17);boot[510..512].copy_from_slice(&[0x55,0xaa]);
    for f in 0..2{let at=base+512+f*17*512;for(c,n)in [(0,0xfff8),(1,0xffff),(2,0xffff),(3,0xffff),(4,0xffff)]{w16(&mut b,at+c*2,n);}}
    let root=base+35*512;b[root..root+32].copy_from_slice(&dirent(b"HELLO   COM",0,2,26));b[root+32..root+64].copy_from_slice(&dirent(b"PKGS       ",16,3,0));
    let data=base+37*512;let hello=super::super::dos::hello("com").unwrap();b[data..data+hello.len()].copy_from_slice(&hello);
    let package=stored("BIN/HELLO.COM",&hello);b[data+512..data+544].copy_from_slice(&dirent(b"PACKAGE ZIP",0,4,package.len()));b[data+1024..data+1024+package.len()].copy_from_slice(&package);b
}
#[test]
fn crc32_known_answer_and_stored_zip_roundtrip(){assert_eq!(crc32(b"123456789"),0xcbf43926);let a=parse(&stored("BIN/A.COM",b"abc"),true).unwrap();assert_eq!(a.files.len(),1);assert_eq!(a.files[0].path,"BIN/A.COM");assert_eq!(a.files[0].bytes,b"abc");}
#[test]
fn fat16_mbr_and_superfloppy_read_original_paths_and_expand_packages(){
    for mbr in [false,true]{let a=parse(&image(mbr),false).unwrap();assert_eq!(a.files.len(),3);assert!(a.files.iter().any(|e|e.path=="PKGS/PACKAGE.ZIP.contents/BIN/HELLO.COM"));assert_eq!(a.files.iter().filter(|e|executable(&e.path)).count(),2);}
}
#[test]
fn fat16_bad_copies_clusters_partitions_and_directories_are_rejected(){
    let good=image(true);let base=63*512;
    let mut b=good.clone();b[base+512+17*512+4]^=1;assert!(parse(&b,false).is_err());
    let mut b=good.clone();for f in 0..2{w16(&mut b,base+512+f*17*512+4,2);}assert!(parse(&b,false).is_err());
    let mut b=good.clone();w32(&mut b,446+12,u32::MAX);assert!(parse(&b,false).is_err());
    let mut b=good.clone();b[base+37*512+512..base+37*512+544].copy_from_slice(&dirent(b"LOOP       ",16,3,0));assert!(parse(&b,false).is_err());
    let mut b=good;w32(&mut b,base+35*512+28,1000);assert!(parse(&b,false).is_err());
}
#[test]
fn zip_rejects_traversal_windows_aliases_crc_encryption_and_metadata_conflicts(){
    for name in ["../escape.com","/abs.com","C:/drive.com","BIN/../bad.com","NUL.txt","BIN/CON","odd./bad.com"]{assert!(parse(&stored(name,b"x"),true).is_err(),"{name}");}
    for at in [14,18,22,30]{let mut b=stored("A.COM",b"test");b[at]^=1;assert!(parse(&b,true).is_err(),"{at}");}
    let mut b=stored("A.COM",b"x");w16(&mut b,6,1);let central=36;w16(&mut b,central+8,1);assert!(parse(&b,true).is_err());
    let mut b=stored("A.COM",b"x");w32(&mut b,36+24,u32::MAX);assert!(parse(&b,true).is_err());
}
#[test]
fn nested_bad_zip_is_retained_with_a_diagnostic_not_silently_lost(){let a=parse(&stored("bad.zip",b"not zip"),true).unwrap();assert_eq!(a.files.len(),1);assert!(a.notes[0].contains("not expanded"));}
#[test]
fn extracting_requires_a_new_directory_and_preserves_files(){
    use std::time::{SystemTime,UNIX_EPOCH};let dir=std::env::temp_dir().join(format!("pil-container-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()));std::fs::create_dir_all(&dir).unwrap();let zip=dir.join("input.zip");std::fs::write(&zip,stored("BIN/A.COM",b"original")).unwrap();let out=dir.join("output");extract(&zip,&out).unwrap();assert_eq!(std::fs::read(out.join("BIN/A.COM")).unwrap(),b"original");assert!(extract(&zip,&out).is_err());assert_eq!(std::fs::read(out.join("BIN/A.COM")).unwrap(),b"original");std::fs::remove_dir_all(dir).unwrap();
}
#[test]
fn image_probe_deduplicates_byte_identical_executables(){
    use std::time::{SystemTime,UNIX_EPOCH};let path=std::env::temp_dir().join(format!("pil-image-{}-{}.img",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()));std::fs::write(&path,image(true)).unwrap();let text=super::super::dos::report(&[path.to_string_lossy().into_owned()],100).unwrap();assert!(text.contains("candidates=2 added_unique=1"),"{text}");assert!(text.contains("SUMMARY imported=1/1 exited=1"));std::fs::remove_file(path).unwrap();
}
#[test]
fn malformed_deflate_inputs_are_bounded_and_fail_without_panics(){
    for b in [vec![],vec![7],vec![1,1,0,0,0],vec![3],vec![255;40]]{assert!(super::super::inflate::decode(&b,10).is_err());}
    let mut seed=0x3456789au32;for len in 0..128{let mut b=Vec::new();for _ in 0..len{seed^=seed<<13;seed^=seed>>17;seed^=seed<<5;b.push(seed as u8);}let _=super::super::inflate::decode(&b,256);}
}

